protected override CreateParams CreateParams {get{var p=base.CreateParams;p.ExStyle|=0x80000;return p;}}
[STAThread] static void Main(string[] args){Application.EnableVisualStyles();try{using(var p=new Pet()){if(args.Length>0&&args[0]=="--check"){int count=0;foreach(var b in p.frames)using(var m=new MemoryStream(b))using(var im=Image.FromStream(m)){if(im.Width!=640||im.Height!=360)throw new Exception("Frame size");count++;}File.WriteAllText(args[1],"Frames="+count+"; FPS=30; Duration="+(count/30.0)+"; Audio="+p.audio.Length+"; OK");return;}Application.Run(p);}}catch(Exception e){MessageBox.Show(e.Message,"阿米娅桌宠");}}
Pet(){Text="阿米娅桌宠"; FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=true;TopMost=true;StartPosition=FormStartPosition.Manual;ClientSize=new Size(480,270);var area=Screen.PrimaryScreen.WorkingArea;Location=new Point(area.Right-Width-30,area.Bottom-Height); using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("frames")) using(var z=new ZipArchive(s,ZipArchiveMode.Read)){foreach(var e in z.Entries){using(var es=e.Open())using(var m=new MemoryStream()){es.CopyTo(m);frames.Add(m.ToArray());}}} audio=new MemoryStream();using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("music"))s.CopyTo(audio);audio.Position=0;music=new SoundPlayer(audio);music.Load();
pause=new ToolStripMenuItem("暂停舞蹈",null,(s,e)=>TogglePause());sound=new ToolStripMenuItem("开启音乐",null,(s,e)=>{muted=!muted;sound.Text=muted?"开启音乐":"关闭音乐";Restart();});menu.Items.Add("阿米娅 · 右键菜单").Enabled=false;menu.Items.Add(pause);menu.Items.Add(sound);menu.Items.Add("重新播放",null,(s,e)=>Restart());var sizes=new ToolStripMenuItem("桌宠大小");foreach(int w in new[]{325,480,640,799}){int width=w;sizes.DropDownItems.Add(w+" 像素",null,(s,e)=>{Size=new Size(width,width*9/16);Clamp();DrawFrame(Math.Max(0,frame));});}menu.Items.Add(sizes);menu.Items.Add("置于顶层",null,(s,e)=>{TopMost=!TopMost;((ToolStripMenuItem)s).Checked=TopMost;}).GetType();((ToolStripMenuItem)menu.Items[5]).Checked=true;menu.Items.Add("移回屏幕右下角",null,(s,e)=>{var a=Screen.PrimaryScreen.WorkingArea;Location=new Point(a.Right-Width,a.Bottom-Height);});menu.Items.Add(new ToolStripSeparator());menu.Items.Add("退出桌宠",null,(s,e)=>Close());PhantomTheme.Apply(menu);ContextMenuStrip=menu;tray=new NotifyIcon{Icon=SystemIcons.Application,Text="阿米娅桌宠 · 右键管理",ContextMenuStrip=menu,Visible=true};tray.DoubleClick+=(s,e)=>{Show();Clamp();};MouseDown+=(s,e)=>{if(e.Button==MouseButtons.Left){drag=e.Location;dragging=true;Capture=true;}};MouseMove+=(s,e)=>{if(dragging){var p=Cursor.Position;Location=new Point(p.X-drag.X,p.Y-drag.Y);}};MouseUp+=(s,e)=>{dragging=false;Capture=false;Clamp();};MouseDoubleClick+=(s,e)=>{if(e.Button==MouseButtons.Left)TogglePause();};timer.Interval=15;timer.Tick+=(s,e)=>TickFrame();Shown+=(s,e)=>{watch.Start();timer.Start();TickFrame();};FormClosed+=(s,e)=>{timer.Stop();music.Stop();tray.Visible=false;tray.Dispose();music.Dispose();audio.Dispose();};}
void Clamp(){var a=Screen.FromPoint(Location).WorkingArea;Location=new Point(Math.Max(a.Left,Math.Min(Left,a.Right-Width)),Math.Max(a.Top,Math.Min(Top,a.Bottom-Height)));}
void Restart(){music.Stop();paused=false;pause.Text="暂停舞蹈";watch.Restart();frame=-1;last=-1;if(!muted)music.Play();TickFrame();}
void TogglePause(){if(paused){Restart();}else{paused=true;watch.Stop();music.Stop();pause.Text="继续舞蹈（从头播放）";}}
void TickFrame(){if(paused)return;long n=watch.ElapsedMilliseconds*30/1000;int i=(int)(n%frames.Count);int cycle=(int)(n/frames.Count);if(cycle!=last){if(!muted){music.Stop();music.Play();}last=cycle;}if(i!=frame){frame=i;DrawFrame(i);}}
